/**
 * Unit tests for NumberSerializer.acceptJsonFormatVisitor
 */
public class NumberSerializer_acceptJsonFormatVisitor_TriageGen0Test {

    @Test
    public void testAcceptJsonFormatVisitor_isIntTrue() throws JsonMappingException {
        // Given: A serializer where _isInt is true. 
        // Since _isInt is a private field, we must use a subclass or a way to trigger it.
        // Based on the provided code, we simulate the behavior by using a subclass 
        // that forces the _isInt field to true if possible, or we use reflection.

        // Note: In Jackson's actual implementation, _isInt is set via the constructor 
        // or internal logic. Here we use a mock/subclass approach.

        NumberSerializer serializer = new NumberSerializer(Integer.class) {
            // We simulate the state of _isInt via a field if we were testing the real class.
            // Since we cannot modify the private field directly without reflection, 
            // we assume the existence of a way to trigger the first branch.
        };

        // Using reflection to set the private field _isInt to true for coverage
        setField(serializer, "_isInt", true);

        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);

        // When
        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        // Then: verify visitIntFormat was called (which calls visitor.expectNumberFormat or similar)
        // In Jackson, visitIntFormat calls visitor.expectNumberFormat(typeHint, JsonParser.NumberType.BIG_INTEGER)
        // or similar depending on version. Based on the provided snippet:
        // visitIntFormat(visitor, typeHint, JsonParser.NumberType.BIG_INTEGER);
        // We verify the visitor interaction.
        verify(visitor).expectNumberFormat(typeHint);
    }

    @Test
    public void testAcceptJsonFormatVisitor_isIntFalse() throws JsonMappingException {
        // Given: A serializer where _isInt is false.
        NumberSerializer serializer = new NumberSerializer(Double.class);
        setField(serializer, "_isInt", false);

        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);

        // When
        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        // Then: The 'else' branch is taken. 
        // The 'if (false)' block is skipped.
        // The 'else' block calls visitor.expectNumberFormat(typeHint).
        verify(visitor).expectNumberFormat(typeHint);
        verify(visitor, never()).expectNumberFormat(any(), any());
    }

    /**
     * Helper method to set private fields for testing purposes.
     */
    private void setField(Object target, String fieldName, Object value) {
        try {
            java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(target, value);
        } catch (Exception e) {
            // If the field is in the superclass
            try {
                java.lang.reflect.Field field = NumberSerializer.class.getDeclaredField(fieldName);
                field.setAccessible(true);
                field.set(target, value);
            } catch (Exception ex) {
                throw new RuntimeException("Failed to set field " + fieldName, ex);
            }
        }
    }
}
